const PALETTES = {
  terracotta: ['#ede4d4','#d8c4a0','#caa479','#b8754f','#974a3a','#642822'],
  sage:       ['#e8e7d6','#c9d2b3','#9eb288','#728c64','#4f6948','#2e4530'],
  slate:      ['#e6ebef','#bdcad4','#8ea1b1','#5e7689','#3d556a','#22344a'],
  rose:       ['#ece1de','#dbb9b9','#c08e95','#9a5e72','#6d3f56','#412236'],
  teal:       ['#dde7e5','#a8c2bf','#6fa097','#487a72','#2e5953','#1a3833'],
  lavender:   ['#e7e1ec','#c5b4d3','#a08abb','#7e639d','#5a417a','#3a2855'],
};
const len = (v) => (typeof v.length === 'number' ? v.length : (v.toArray ? v.toArray().length : 0));
const at  = (v, i) => (typeof v.get === 'function' ? v.get(i) : v[i]);

const series = context.panel.data.series && context.panel.data.series[0];
if (!series || !series.fields) return {};
const f = (n) => { const x = series.fields.find(x => x.name === n); return x ? x.values : null; };
const kindF = f('kind');
const hourF = f('hour');
const cntF  = f('count');
const sampF = f('samples');
if (!kindF || !hourF || !cntF || len(kindF) === 0) return {};

const paletteName = context.grafana.replaceVariables('${palette}');
const stops = PALETTES[paletteName] || PALETTES.slate;
const NEUTRAL_BAR = stops[3];
const venueName = context.grafana.replaceVariables('${venue}');

const fmtHour = new Intl.DateTimeFormat('en-GB', { hour: 'numeric', hour12: false, timeZone: 'Asia/Taipei' });
const currentHour = parseInt(fmtHour.format(new Date()), 10);
const weekdayShort = new Intl.DateTimeFormat('en', { weekday: 'short', timeZone: 'Asia/Taipei' }).format(new Date());

const typicalRows = [];
let nowRow = null;
for (let i = 0; i < len(kindF); i++) {
  const kind = at(kindF, i);
  const hour = at(hourF, i);
  const count = at(cntF, i);
  const samples = at(sampF, i);
  if (kind === 'typical') typicalRows.push({ hour, count, samples });
  else if (kind === 'now') nowRow = { hour, count };
}
typicalRows.sort((a, b) => a.hour - b.hour);
if (typicalRows.length === 0) return {};

const hours = typicalRows.map(r => String(r.hour).padStart(2, '0') + ':00');
const barData = typicalRows.map(r => ({
  value: r.count,
  itemStyle: { color: r.hour === currentHour ? stops[5] : NEUTRAL_BAR },
}));

const scatterData = [];
if (nowRow != null) {
  const xIdx = typicalRows.findIndex(r => r.hour === nowRow.hour);
  if (xIdx >= 0) {
    scatterData.push({
      value: [xIdx, nowRow.count],
      label: { show: true, formatter: '現在: ' + nowRow.count + ' 人', position: 'top', color: '#fafafa', fontSize: 12, fontWeight: 'bold' },
      symbol: 'none',
    });
  }
}

return {
  title: { text: '今日 (' + weekdayShort + ') · ' + venueName, left: 'center', top: 6, textStyle: { color: '#ddd', fontSize: 13, fontWeight: 'normal' } },
  grid: { left: 50, right: 30, top: 50, bottom: 30, containLabel: true },
  xAxis: { type: 'category', data: hours, axisLabel: { color: '#aaa', fontSize: 10 } },
  yAxis: { type: 'value', name: '人', nameTextStyle: { color: '#888', fontSize: 10 }, axisLabel: { color: '#888', fontSize: 10 }, splitLine: { lineStyle: { color: '#222' } } },
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      if (p.seriesType === 'scatter') return '現在: ' + (nowRow ? nowRow.count : '-') + ' 人';
      const r = typicalRows[p.dataIndex];
      return weekdayShort + ' ' + hours[p.dataIndex] + '<br/>' + '平均 ' + Number(r.count).toFixed(0) + ' 人<br/>' + '樣本 ' + r.samples + ' 週';
    },
  },
  series: [
    { type: 'bar', data: barData, barWidth: '60%' },
    { type: 'scatter', data: scatterData, symbolSize: 0, z: 5 },
  ],
};

const PALETTES = {  terracotta: ['#ede4d4','#d8c4a0','#caa479','#b8754f','#974a3a','#642822'],
  sage:       ['#e8e7d6','#c9d2b3','#9eb288','#728c64','#4f6948','#2e4530'],
  slate:      ['#e6ebef','#bdcad4','#8ea1b1','#5e7689','#3d556a','#22344a'],
  rose:       ['#ece1de','#dbb9b9','#c08e95','#9a5e72','#6d3f56','#412236'],
  teal:       ['#dde7e5','#a8c2bf','#6fa097','#487a72','#2e5953','#1a3833'],
  lavender:   ['#e7e1ec','#c5b4d3','#a08abb','#7e639d','#5a417a','#3a2855'],
};

const series = context.panel.data.series && context.panel.data.series[0];
if (!series || !series.fields) return {};
const hexToRgb = (h) => [parseInt(h.slice(1,3),16), parseInt(h.slice(3,5),16), parseInt(h.slice(5,7),16)];
const lerpChan = (a, b, t) => Math.round(a + (b - a) * t);
const interpStops = (r) => {
  if (r <= 0) return stops[0];
  if (r >= 100) return stops[5];
  const idx = r / 20;
  const i0 = Math.floor(idx);
  const i1 = Math.min(5, i0 + 1);
  const t = idx - i0;
  const c0 = hexToRgb(stops[i0]);
  const c1 = hexToRgb(stops[i1]);
  return '#' + [0,1,2].map(k => lerpChan(c0[k], c1[k], t).toString(16).padStart(2, '0')).join('');
};
const labelFg = (r) => {
  const [rr, gg, bb] = hexToRgb(interpStops(r));
  return (0.299 * rr + 0.587 * gg + 0.114 * bb) > 150 ? '#1a1a1a' : '#fafafa';
};
const len = (v) => (typeof v.length === 'number' ? v.length : (v.toArray ? v.toArray().length : 0));
const at  = (v, i) => (typeof v.get === 'function' ? v.get(i) : v[i]);

const field = (n) => { const f = series.fields.find(x => x.name === n); return f ? f.values : null; };
const wd     = field('weekday_number');
const slot   = field('slot_label');
const cnt    = field('avg_count');
const ratio  = field('crowding_ratio');
const samp   = field('sample_count');
if (!wd || !slot || !cnt || !ratio || !samp || len(wd) === 0) return {};

const paletteName = context.grafana.replaceVariables('${palette}');
const stops = PALETTES[paletteName] || PALETTES.slate;
const metric = context.grafana.replaceVariables('${metric}');

const DAYS = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];

// Operating hours per weekday in minutes-since-midnight (isodow: 1=Mon..7=Sun)
const OPEN_HOURS_MIN = {
  1: [6*60, 22*60], 2: [6*60, 22*60], 3: [6*60, 22*60],
  4: [6*60, 22*60], 5: [6*60, 22*60],   // Mon-Fri 06:00-22:00
  6: [9*60, 22*60],                     // Sat 09:00-22:00
  7: [9*60, 18*60],                     // Sun 09:00-18:00
};

// Build the full y-axis covering every weekday's widest range (06:00-22:00)
// regardless of which slots have data. Cells outside a weekday's operating
// hours render as "closed"; cells inside hours but missing data render
// as transparent gaps.
const granularity = context.grafana.replaceVariables('${granularity}');
const stepMin = granularity === '60min' ? 60 : 30;
const rangeStartMin = 6 * 60;
const rangeEndMin   = 22 * 60;
const yCats = [];
const ySlotMins = [];
for (let m = rangeStartMin; m < rangeEndMin; m += stepMin) {
  const h = Math.floor(m / 60), mm = m % 60;
  yCats.push(String(h).padStart(2,'0') + ':' + String(mm).padStart(2,'0'));
  ySlotMins.push(m);
}

// Look up SQL rows by (weekday, slot_label)
const lookup = {};
for (let i = 0; i < len(wd); i++) {
  lookup[at(wd, i) + '|' + at(slot, i)] = {
    cnt: at(cnt, i),
    ratio: at(ratio, i),
    samp: at(samp, i),
  };
}

const heatData = [];
for (let xIdx = 0; xIdx < 7; xIdx++) {
  const weekday = xIdx + 1;
  const [openMin, closeMin] = OPEN_HOURS_MIN[weekday];
  for (let yIdx = 0; yIdx < yCats.length; yIdx++) {
    const slotLabel = yCats[yIdx];
    const slotMin   = ySlotMins[yIdx];
    const isOpen = slotMin >= openMin && slotMin < closeMin;
    const data = lookup[weekday + '|' + slotLabel];
    if (data) {
      const c = Math.round(data.cnt);
      const r = Math.round(data.ratio * 100);
      heatData.push({
        value: [xIdx, yIdx, r, c, r + '%', data.samp],
        label: { color: labelFg(r) },
      });
    } else if (!isOpen) {
      heatData.push({
        value: [xIdx, yIdx, 0, 'closed', 'closed', 0],
        itemStyle: { color: '#202020', borderColor: '#0a0a0a' },
        label: { color: '#666', show: true, fontStyle: 'italic', formatter: 'closed' },
      });
    }
    // else: in operating hours but no data — skip (transparent gap)
  }
}

const labelIdx = metric === 'crowding_ratio' ? 4 : 3;


return {
  grid:    { left: 60, right: 30, top: 40, bottom: 60, containLabel: true },
  xAxis:   { type: 'category', data: DAYS, position: 'top', axisLabel: { color: '#aaa' }, splitArea: { show: false } },
  yAxis:   { type: 'category', data: yCats, inverse: true, axisLabel: { color: '#aaa', fontSize: 10 } },
  visualMap: {
    type: 'continuous', dimension: 2,
    min: 0, max: 100, calculable: true,
    orient: 'horizontal', left: 'center', bottom: 5,
    inRange: { color: stops },
    text: ['100%', '0%'],
    textStyle: { color: '#aaa' },
  },
  tooltip: {
    formatter: (p) => {
      const [x, y, r, c, _rp, s] = p.value;
      return DAYS[x] + ' ' + yCats[y] + '<br/>' +
             'avg_count: ' + c + ' 人<br/>' +
             'crowding_ratio: ' + r + '%<br/>' +
             'sample_count: ' + s + ' 週';
    },
  },
  series: [{
    type: 'heatmap',
    data: heatData,
    label: {
      show: true,
      formatter: (p) => String(p.value[labelIdx]),
      fontSize: 10,
    },
    emphasis: { itemStyle: { borderColor: '#fff', borderWidth: 1 } },
  }],
};

const PALETTES = {
  terracotta: ['#ede4d4','#d8c4a0','#caa479','#b8754f','#974a3a','#642822'],
  sage:       ['#e8e7d6','#c9d2b3','#9eb288','#728c64','#4f6948','#2e4530'],
  slate:      ['#e6ebef','#bdcad4','#8ea1b1','#5e7689','#3d556a','#22344a'],
  rose:       ['#ece1de','#dbb9b9','#c08e95','#9a5e72','#6d3f56','#412236'],
  teal:       ['#dde7e5','#a8c2bf','#6fa097','#487a72','#2e5953','#1a3833'],
  lavender:   ['#e7e1ec','#c5b4d3','#a08abb','#7e639d','#5a417a','#3a2855'],
};

const series = context.panel.data.series && context.panel.data.series[0];
if (!series || !series.fields) return {};
const timeF = series.fields.find(f => f.type === 'time');
const valF  = series.fields.find(f => f.type === 'number');
if (!timeF || !valF) return {};

const len = (v) => (typeof v.length === 'number' ? v.length : (v.toArray ? v.toArray().length : 0));
const at  = (v, i) => (typeof v.get === 'function' ? v.get(i) : v[i]);

const lineColor = (PALETTES[context.grafana.replaceVariables('${palette}')] || PALETTES.slate)[2];

// Build a category (ordinal) x-axis: each data point becomes one slot,
// non-operating hours simply don't appear on the axis at all (the
// Highstock-style "ordinal" convention used by financial charts).
// One category per reading, keyed by "YYYY-MM-DD HH:MM" so multiple
// Mondays don't collide. Day boundaries are recorded for a markLine.
const cats = [];
const vals = [];
const dayBoundaries = [];
let prevDay = null;
for (let i = 0; i < len(timeF.values); i++) {
  const t = at(timeF.values, i);
  const v = at(valF.values, i);
  const d = new Date(t);
  const day = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Taipei' }).format(d);
  const tm  = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Asia/Taipei' }).format(d);
  cats.push(day + ' ' + tm);
  vals.push(v);
  if (prevDay !== null && prevDay !== day) {
    dayBoundaries.push({
      xAxis: cats.length - 1,
      lineStyle: { color: 'rgba(255,255,255,0.18)', type: 'dashed', width: 1 },
      label: { show: false },
    });
  }
  prevDay = day;
}

return {
  grid: { left: 50, right: 20, top: 20, bottom: 38 },
  xAxis: {
    type: 'category',
    data: cats,
    boundaryGap: false,
    axisLabel: {
      color: '#aaa',
      hideOverlap: true,
      formatter: (cat) => {
        const [day, tm] = cat.split(' ');
        const wd = new Intl.DateTimeFormat('en', { weekday: 'short', timeZone: 'Asia/Taipei' }).format(new Date(day + 'T00:00:00+08:00'));
        return wd + '\n' + tm;
      },
    },
  },
  yAxis: { type: 'value', axisLabel: { color: '#aaa' }, name: '人', nameTextStyle: { color: '#aaa' } },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'cross', lineStyle: { color: 'rgba(255,255,255,0.3)' } },
    formatter: (p) => {
      const cat = p[0].axisValue;
      const [day, tm] = cat.split(' ');
      const wd = new Intl.DateTimeFormat('en', { weekday: 'short', timeZone: 'Asia/Taipei' }).format(new Date(day + 'T00:00:00+08:00'));
      return wd + ' ' + tm + '<br/>' + p[0].value + ' 人';
    },
  },
  series: [{
    type: 'line',
    data: vals,
    showSymbol: false,
    symbol: 'circle',
    symbolSize: 8,
    lineStyle: { color: lineColor, width: 1.8 },
    itemStyle: { color: lineColor },
    areaStyle: { color: lineColor, opacity: 0.1 },
    emphasis: {
      itemStyle: { color: '#ffffff', borderColor: lineColor, borderWidth: 2 },
      scale: false,
    },
    markLine: { silent: true, symbol: 'none', data: dayBoundaries },
  }],
};

const PALETTES = {
  terracotta: ['#ede4d4','#d8c4a0','#caa479','#b8754f','#974a3a','#642822'],
  sage:       ['#e8e7d6','#c9d2b3','#9eb288','#728c64','#4f6948','#2e4530'],
  slate:      ['#e6ebef','#bdcad4','#8ea1b1','#5e7689','#3d556a','#22344a'],
  rose:       ['#ece1de','#dbb9b9','#c08e95','#9a5e72','#6d3f56','#412236'],
  teal:       ['#dde7e5','#a8c2bf','#6fa097','#487a72','#2e5953','#1a3833'],
  lavender:   ['#e7e1ec','#c5b4d3','#a08abb','#7e639d','#5a417a','#3a2855'],
};
const len = (v) => (typeof v.length === 'number' ? v.length : (v.toArray ? v.toArray().length : 0));
const at  = (v, i) => (typeof v.get === 'function' ? v.get(i) : v[i]);
const hexToRgb = (h) => [parseInt(h.slice(1,3),16), parseInt(h.slice(3,5),16), parseInt(h.slice(5,7),16)];
const lerpChan = (a, b, t) => Math.round(a + (b - a) * t);
const interpStops = (stops, r) => {
  if (r <= 0) return stops[0];
  if (r >= 100) return stops[5];
  const idx = r / 20;
  const i0 = Math.floor(idx);
  const i1 = Math.min(5, i0 + 1);
  const t = idx - i0;
  const c0 = hexToRgb(stops[i0]); const c1 = hexToRgb(stops[i1]);
  return '#' + [0,1,2].map(k => lerpChan(c0[k], c1[k], t).toString(16).padStart(2, '0')).join('');
};

const series = context.panel.data.series && context.panel.data.series[0];
if (!series || !series.fields) return {};
const f = (n) => { const x = series.fields.find(x => x.name === n); return x ? x.values : null; };
const kindF = f('kind');
const venueF = f('venue');
const tsF = f('ts_ms');
const cntF = f('current_count');
const medF = f('hist_median');
const difF = f('diff');
const ratioF = f('ratio');
const cmfF = f('comfortable');
const capF = f('capacity');
if (!kindF || !venueF || !cntF || len(kindF) === 0) return {};

const paletteName = context.grafana.replaceVariables('${palette}');
const stops = PALETTES[paletteName] || PALETTES.slate;

const venues = {};
for (let i = 0; i < len(kindF); i++) {
  const kind = at(kindF, i);
  const venue = at(venueF, i);
  if (!venues[venue]) venues[venue] = { summary: null, readings: [] };
  if (kind === 'summary') {
    venues[venue].summary = { count: at(cntF, i), median: at(medF, i), diff: at(difF, i), ratio: at(ratioF, i), comfortable: at(cmfF, i), capacity: at(capF, i) };
  } else if (kind === 'reading') {
    venues[venue].readings.push([at(tsF, i), at(cntF, i)]);
  }
}
const venueNames = Object.keys(venues).sort();
if (venueNames.length === 0) return {};

const padReadings = (rows) => {
  if (rows.length <= 1) return rows;
  const out = [rows[0]];
  for (let i = 1; i < rows.length; i++) {
    const gapMs = rows[i][0] - rows[i-1][0];
    if (gapMs > 60 * 60 * 1000) {
      out.push([rows[i-1][0] + 1, null]);
      out.push([rows[i][0] - 1, null]);
    }
    out.push(rows[i]);
  }
  return out;
};

const grids = [];
const xAxes = [];
const yAxes = [];
const seriesOut = [];
const graphicEls = [];
const lineColor = stops[3];

venueNames.slice(0, 2).forEach((vname, idx) => {
  const isLeft = idx === 0;
  const leftPct = isLeft ? 2 : 52;
  const rightPct = isLeft ? 52 : 2;
  grids.push({ left: leftPct + '%', right: rightPct + '%', top: 110, bottom: 14 });
  xAxes.push({ type: 'time', show: false, gridIndex: idx });
  yAxes.push({ type: 'value', show: false, gridIndex: idx, min: 0 });

  const v = venues[vname];
  const data = padReadings(v.readings || []);
  const lastIdx = data.length - 1;
  seriesOut.push({
    type: 'line', name: vname, data: data,
    xAxisIndex: idx, yAxisIndex: idx,
    showSymbol: false, connectNulls: false,
    lineStyle: { color: lineColor, width: 1.6 },
    itemStyle: { color: lineColor },
    markPoint: lastIdx >= 0 && data[lastIdx][1] != null ? {
      symbol: 'circle', symbolSize: 8,
      itemStyle: { color: '#fff', borderColor: lineColor, borderWidth: 1.5 },
      label: { show: false },
      data: [{ coord: data[lastIdx] }],
    } : undefined,
  });

  const s = v.summary;
  if (!s) return;
  const ratioPct = Math.round((s.ratio || 0) * 100);
  const bigCol = interpStops(stops, ratioPct);
  const cmfPct = s.comfortable ? Math.round((s.count / s.comfortable) * 100) + '%' : '—';
  const capPct = s.capacity ? Math.round((s.count / s.capacity) * 100) + '%' : '—';
  const subtitle = '舒適 ' + cmfPct + ' · 容量 ' + capPct;
  const diff = Number(s.diff || 0);
  const diffColor = diff > 0 ? stops[3] : (diff < 0 ? stops[1] : '#888');
  const arrow = diff > 0 ? '↑' : (diff < 0 ? '↓' : '–');
  const diffText = arrow + ' ' + Math.abs(diff).toFixed(0) + ' vs 同時段中位數';
  const xCenterPct = isLeft ? '25%' : '75%';
  graphicEls.push(
    { type: 'text', left: xCenterPct, top: 12, style: { text: vname, fill: '#9aa', fontSize: 12, textAlign: 'center' } },
    { type: 'text', left: xCenterPct, top: 30, style: { text: String(s.count), fill: bigCol, fontSize: 40, fontWeight: 'lighter', textAlign: 'center' } },
    { type: 'text', left: xCenterPct, top: 78, style: { text: subtitle, fill: '#888', fontSize: 11, textAlign: 'center' } },
    { type: 'text', left: xCenterPct, top: 94, style: { text: diffText, fill: diffColor, fontSize: 12, textAlign: 'center' } },
  );
});

return {
  grid: grids,
  xAxis: xAxes,
  yAxis: yAxes,
  series: seriesOut,
  graphic: { elements: graphicEls },
  tooltip: { trigger: 'axis', axisPointer: { type: 'cross' } },
};
